import { Box } from '../common'
import { CustomTypes } from '..'
import { IBase } from './base'
import { ObjectFamily } from 'rendevoz'
import { MetaFormLayoutItem } from '~/typings'
import { Dispatch, SetStateAction } from 'react'

export type IMetaAttachment =
  | {
      type: MetaObject['type']
      id: MetaObject['id']
      createdAt: number
    }
  | {
      type: 'attachmentText'
      id: number
      createdAt: number
      text: string
    }

export type BuiltInMetaObjectTypes =
  | 'note'
  | 'pdf'
  | 'pdfLabel'
  | 'normal'
  | 'image'
  | 'whiteboard'
  | 'video'
  | 'audio'
  | 'webpage'
  | 'noteLabel'
  | 'noteBlock'
  | 'webpageLabel'
  | 'localFile'
  | 'videoLabel'
  | 'group'
  | 'syncedBlock'
  | 'code'
  | 'question'

export type IMetaSelectOption = {
  name: string
  color: string
  parentPropName: string
  order?: number
} & IBase

export type IMetaProperty = (
  | {
      propType: 'string'
      value?: string
    }
  | {
      propType: 'AI summary'
      value?: string
    }
  | {
      propType: 'AI questions'
      value?: number[]
    }
  | {
      propType: 'file'
      value?: {
        type: string
        name: string
        path: string
      }[]
    }
  | {
      propType: 'number'
      value?: number
    }
  | {
      propType: 'checkbox'
      value?: boolean
    }
  | {
      propType: 'number array'
      value?: number[]
    }
  | {
      propType: 'singleSelect'
      // id
      value?: number
    }
  | {
      propType: 'multiSelect'
      // id array
      value?: number[]
    }
  | {
      propType: 'URL'
      value?: string
    }
  | {
      propType: 'date'
      // milliseconds, Date.now
      value?: number
    }
) & {
  icon?: string
}

// sourceType: note / metaObject / pdf document
export interface MetaObject extends IBase {
  type: BuiltInMetaObjectTypes
  workspace: number
  name?: string
  description?: string
  coverImgSrc?: string
  // preview image generated by html2image
  previewImgSrc?: string
  objectId?: number
  objectUrl?: string
  tags?: number[]
  icon?: string
  color?: string
  // hidden by group
  hidden?: boolean
  attachments?: IMetaAttachment[]
  // placeholder name mainly for labels, like original text
  placeholderName?: string
  // id to prop
  properties?: Record<number | string, IMetaProperty>
  fromObject?:
    | {
        type: 'pdf'
        metaId: number
        pages?: number[]
        rect?: Box
        selectedText?: string
      }
    | {
        type: 'note'
        metaId: number
        blockId?: number
        selectedText?: string
      }
    | {
        type: 'webpage'
        metaId: number
        blockId?: number
        selectedText?: string
      }
    | {
        type: 'whiteboard'
        metaId: number
      }
    | {
        type: 'video'
        metaId: number
        time?: number
      }
  temp?: boolean
}

export type RegisteredMetaObject<T = MetaObject['type']> = {
  type: T
  onNavigate?: (metaObject: MetaObject & { type: T }) => void
  icon: string
  /**
   * Default name for created meta-object
   */
  defaultName?: string | (() => string)
  i18nKey: string
  /**
   * If set true, will be visible in homepage
   * Default: true
   */
  visibleInHomepage?: boolean
  /**
   * If set true, will be visible in create menu like homepage menu or collection menu
   * Default: false
   */
  visibleInCreateMenu?: boolean
  filterSettings: {
    /**
     * TODO: Custom object type
     */
    objectType: 'record' | 'file' | 'label'
  }
  graphSettings?: {
    collisionRadius?: number
    /**
     * Default radius: 45
     */
    radius?: number
  }
  /**
   * Customize your meta-object edit details form
   */
  customEditForm?: (
    metaObject: MetaObject & { type: T },
    setMetaObject: Dispatch<SetStateAction<MetaObject>>,
    object?: ObjectFamily[T]
  ) => MetaFormLayoutItem[]
  /**
   * Difference between onCreate and onAdd:
   * onCreate is only triggered when meta-object is created in menus like homepage menu, collection menu
   * onAdd will always be triggered when meta-object is added
   * So if meta-object is created, onCreate and onAdd will all be triggered
   * You can do works like navigating or toasting onCreate
   * @param object corresponding object
   */
  onCreate?: (metaObject: MetaObject & { type: T }, object: ObjectFamily[T]) => void
  onAdd?: (metaObject: MetaObject & { type: T }) => void
  onDelete?: (metaObject: MetaObject & { type: T }) => void
  onUpdate?: (
    currMetaObject: MetaObject & { type: T },
    prevMetaObject: MetaObject & { type: T },
    changedProps?: { propName: string; prevProp: any; currProp: any }[]
  ) => void
}

export type StringFieldFilterRule = {
  type: 'contains' | 'not contains' | 'is' | 'is not' | 'starts with' | 'ends with' | 'empty' | 'not empty'
  value: string
}
export type DateFieldFilterRule = {
  type: 'is' | 'before' | 'after' | 'empty' | 'not empty' | 'on and before' | 'on and after'
  value: 'today' | 'yesterday' | 'one week ago' | 'one month ago' | 'three month ago' | 'specific'
  specDate: number
}
type TagFieldFilterRule = {
  type: 'contains' | 'not contains' | 'empty' | 'not empty' | 'is' | 'is not'
  value?: number[]
  tagIds?: number[]
}

type TypeFieldFilterRule = {
  type: 'is' | 'is not'
  filterType: 'rule'
  value: string
}

export type MetaFilterer =
  | {
      metaType: 'spec'
      metaId: number
    }
  | {
      metaType: 'rule'
      group: MetaFilterGroup
    }
export type FromFieldFilterRule = {
  type: 'is'
} & MetaFilterer

export type SingleSelectFilterRule = {
  type: 'empty' | 'not empty' | 'is' | 'is not'
  value?: number
}

export type MultiSelectFilterRule = {
  type: 'contains' | 'not contains' | 'empty' | 'not empty'
  value?: number[]
}

export type MetaFilterGroup = {
  groupType: 'and' | 'or'
  rules: MetaFilterRule[]
  filterType: 'group'
}
export type LinkFilterRule = {
  filterType: 'link'
  type: 'source' | 'target' | 'related'
  ruleType: 'contains' | 'not contains' | 'is' | 'is not'
} & MetaFilterer

export type NumberFieldFilterRule = {
  value?: number
  type: 'is' | 'is not' | 'gt' | 'gte' | 'lt' | 'lte' | 'empty' | 'not empty'
}

export type CheckboxFilterRule = {
  value?: boolean
  type: 'is' | 'is not'
}
export type PropertyFilterRule = {
  filterType: 'rule'
  field: string
} & (
  | ({
      propType: 'checkbox'
    } & CheckboxFilterRule)
  | ({
      propType: 'singleSelect'
    } & SingleSelectFilterRule)
  | ({
      propType: 'multiSelect'
    } & MultiSelectFilterRule)
  | ({
      propType: 'string' | 'URL' | 'AI summary'
    } & StringFieldFilterRule)
  | ({
      propType: 'number'
    } & NumberFieldFilterRule)
  | ({
      propType: 'date'
    } & DateFieldFilterRule)
)

export type MetaFilterRule = (
  | ({
      filterType: 'rule'
      field: 'name'
    } & StringFieldFilterRule)
  | ({
      filterType: 'rule'
      field: 'description'
    } & StringFieldFilterRule)
  | ({
      filterType: 'rule'
      field: 'createdAt' | 'viewAt' | 'updatedAt'
    } & DateFieldFilterRule)
  | ({
      filterType: 'rule'
      field: 'tags'
    } & TagFieldFilterRule)
  | ({
      filterType: 'rule'
      field: 'fromObject'
    } & FromFieldFilterRule)
  | ({ filterType: 'rule'; field: 'type' } & TypeFieldFilterRule)
  | LinkFilterRule
  | MetaFilterGroup
  | PropertyFilterRule
) & {
  id: number
}

export interface MetaLink extends IBase {
  sourceId: number
  sourceType: string
  targetId: number
  targetType: string
  label: string
  color?: string
}
